{
  "description": "The creature is a large quadrupedal mammal shown in right-facing profile standing on a plain light background. Its entire body except the back is covered in dense, shaggy brown fur that is dark brown on the lower legs and hindquarters and lighter tan-brown on the face, neck, chest and belly. The head is broad and bear-like with a blunt snout, dark eyes and a closed mouth. Two dark horns project from the face. A large, glossy, dark brown domed shell covers the whole dorsal surface from the back of the neck to the rump, with a smooth reflective surface, fine longitudinal ridges on the posterior half and a segmented rim along its lower edge. The animal stands on four thick, heavily furred limbs ending in clawed paws, and a small furry tuft of tail is visible at the rear beneath the shell.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad bear-like head covered in light to medium brown shaggy fur with a blunt snout, black nostrils, small dark eyes and a slightly upturned mouth line",
      "where": "at the anterior end of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "two dark gray-black keratinous horns; a large long curved horn rising upward from the tip of the snout and a much smaller short pointed horn centered just above and between the eyes",
      "where": "on the dorsal surface of the snout and forehead"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded densely furred ears with dark brown fur",
      "where": "on the top of the head, one slightly behind the other in profile view"
    },
    {
      "part": "legs",
      "looks_like": "four stout columnar limbs covered in long shaggy dark brown fur, thicker at the upper portion",
      "where": "extending ventrally from the torso, two forelegs under the chest and two hindlegs under the rump"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with dark pads and several long curved pale claws projecting forward from each toe",
      "where": "at the distal ends of the four legs in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a small short tuft of dark brown fur",
      "where": "protruding posteriorly from the rump just beneath the rear edge of the shell"
    },
    {
      "part": "shell",
      "looks_like": "a large glossy dark brown domed carapace divided into an anterior smooth shield over the shoulders and a larger posterior dome with fine parallel longitudinal ridges and a slightly reflective surface",
      "where": "covering the entire dorsal back from the base of the neck to above the hind legs"
    },
    {
      "part": "plates",
      "looks_like": "a row of small rectangular dark brown marginal plates forming a segmented border",
      "where": "along the ventral rim of the shell, most visible around the posterior dome"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
